import{_ as a,o as e,c as n,a5 as s}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"环境准备：安装 Python 与版本管理","description":"本章面向已经会写 Python、需要在一台机器上准备好 Python 环境或管理多个版本的读者。环境已装好 Python 3.13 及以上版本的，可直接跳过本章，进入值、变量与类型。","frontmatter":{"type":"howto","level":"basic"},"headers":[],"relativePath":"python/01-python-language/chapter-00-getting-started.md","filePath":"python/01-python-language/chapter-00-getting-started.md"}'),p={name:"python/01-python-language/chapter-00-getting-started.md"};function o(d,t,r,l,i,h){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="环境准备-安装-python-与版本管理" tabindex="-1" data-src-line="2" data-src-file="python/01-python-language/chapter-00-getting-started.md">环境准备：安装 Python 与版本管理 <a class="header-anchor" href="#环境准备-安装-python-与版本管理" aria-label="Permalink to &quot;环境准备：安装 Python 与版本管理&quot;">​</a></h1><p data-src-line="4" data-src-file="python/01-python-language/chapter-00-getting-started.md">本章面向已经会写 Python、需要在一台机器上准备好 Python 环境或管理多个版本的读者。环境已装好 Python 3.13 及以上版本的，可直接跳过本章，进入<a href="./chapter-01-values-and-variables.html">值、变量与类型</a>。</p><h2 id="_1-安装-python" tabindex="-1" data-src-line="6" data-src-file="python/01-python-language/chapter-00-getting-started.md">1. 安装 Python <a class="header-anchor" href="#_1-安装-python" aria-label="Permalink to &quot;1. 安装 Python&quot;">​</a></h2><p data-src-line="8" data-src-file="python/01-python-language/chapter-00-getting-started.md">按你的操作系统选一种方式。</p><p data-src-line="10" data-src-file="python/01-python-language/chapter-00-getting-started.md"><strong>macOS</strong></p><p data-src-line="12" data-src-file="python/01-python-language/chapter-00-getting-started.md">用 Homebrew 安装最简单。先在终端运行 <code>brew --version</code>，能输出版本号说明已安装 Homebrew；然后：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install python</span></span></code></pre></div><p data-src-line="18" data-src-file="python/01-python-language/chapter-00-getting-started.md"><strong>Windows</strong></p><p data-src-line="20" data-src-file="python/01-python-language/chapter-00-getting-started.md">到 python.org 的下载页，下载最新的 Windows 安装器（64 位）。运行安装器时<strong>务必勾选 &quot;Add python.exe to PATH&quot;</strong>，再点 Install。不勾选的话，之后在终端里敲 <code>python</code> 会提示找不到命令。</p><p data-src-line="22" data-src-file="python/01-python-language/chapter-00-getting-started.md"><strong>Linux</strong></p><p data-src-line="24" data-src-file="python/01-python-language/chapter-00-getting-started.md">大多数发行版自带 Python，或用包管理器安装：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install python3</span></span></code></pre></div><h2 id="_2-验证安装" tabindex="-1" data-src-line="30" data-src-file="python/01-python-language/chapter-00-getting-started.md">2. 验证安装 <a class="header-anchor" href="#_2-验证安装" aria-label="Permalink to &quot;2. 验证安装&quot;">​</a></h2><p data-src-line="32" data-src-file="python/01-python-language/chapter-00-getting-started.md">打开终端，运行：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 --version</span></span></code></pre></div><p data-src-line="38" data-src-file="python/01-python-language/chapter-00-getting-started.md">成功标志：输出形如 <code>Python 3.14.8</code> 的一行版本号。版本号在 3.13 或更高即可，本章与后续章节都能正常进行。写作时的最新稳定版是 Python 3.15，旧一些的 3.13、3.14 同样可用。</p><p data-src-line="40" data-src-file="python/01-python-language/chapter-00-getting-started.md">Windows 上如果安装时勾选了 PATH，命令通常是 <code>python --version</code> 而不是 <code>python3</code>。两个都试一下，哪个能输出版本号就用哪个。下文统一写 <code>python3</code>，你在 Windows 上换成 <code>python</code> 即可。</p><p data-src-line="42" data-src-file="python/01-python-language/chapter-00-getting-started.md">如果提示 <code>command not found</code>（或 Windows 的「不是内部或外部命令」），回到第 1 步检查 PATH 是否配置，或重装一次并确认勾选了 PATH。</p><h2 id="_3-管理多个-python-版本" tabindex="-1" data-src-line="44" data-src-file="python/01-python-language/chapter-00-getting-started.md">3. 管理多个 Python 版本 <a class="header-anchor" href="#_3-管理多个-python-版本" aria-label="Permalink to &quot;3. 管理多个 Python 版本&quot;">​</a></h2><p data-src-line="46" data-src-file="python/01-python-language/chapter-00-getting-started.md">同一台机器常需要同时保留多个 Python 版本（比如 3.11 跑旧项目、3.13 跑新项目）。用版本管理器 pyenv 按目录切换版本：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 安装 pyenv（macOS 用 Homebrew）</span></span>
<span class="line"><span>brew install pyenv</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 列出可安装的版本</span></span>
<span class="line"><span>pyenv install --list</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 安装指定版本</span></span>
<span class="line"><span>pyenv install 3.13.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 在当前目录使用某个版本</span></span>
<span class="line"><span>pyenv local 3.13.0</span></span></code></pre></div><p data-src-line="62" data-src-file="python/01-python-language/chapter-00-getting-started.md"><code>pyenv local</code> 会在当前目录写入一个 <code>.python-version</code> 文件，进入该目录后 <code>python</code> 自动指向对应版本。这样每个项目都能固定自己的解释器版本，避免全局升级破坏旧项目。</p><p data-src-line="64" data-src-file="python/01-python-language/chapter-00-getting-started.md">虚拟环境（venv）解决的是「每个项目一套依赖」，与 pyenv 解决「每个项目一个解释器版本」是两个正交的问题，两者常配合使用，详见<a href="./../02-python-engineering/chapter-01-project-and-testing.html">依赖管理与测试</a>。</p><h2 id="_4-运行-python-代码的三种方式" tabindex="-1" data-src-line="66" data-src-file="python/01-python-language/chapter-00-getting-started.md">4. 运行 Python 代码的三种方式 <a class="header-anchor" href="#_4-运行-python-代码的三种方式" aria-label="Permalink to &quot;4. 运行 Python 代码的三种方式&quot;">​</a></h2><p data-src-line="68" data-src-file="python/01-python-language/chapter-00-getting-started.md">验证环境可用，通常用下面三种方式之一：</p><ul data-src-line="70" data-src-file="python/01-python-language/chapter-00-getting-started.md"><li data-src-line="70" data-src-file="python/01-python-language/chapter-00-getting-started.md"><strong>交互式环境（REPL）</strong>：终端输入 <code>python3</code> 回车，提示符变成 <code>&gt;&gt;&gt;</code>，输入代码回车立即执行，<code>exit()</code> 退出。适合随手验证语法。</li><li data-src-line="71" data-src-file="python/01-python-language/chapter-00-getting-started.md"><strong>脚本文件</strong>：把代码写进 <code>.py</code> 文件，用 <code>python3 hello.py</code> 运行。这是日常写程序的方式。</li><li data-src-line="72" data-src-file="python/01-python-language/chapter-00-getting-started.md"><strong><code>python -m</code> 模块方式</strong>：<code>python3 -m http.server</code> 这样以模块方式运行标准库或包，等价于执行模块的入口代码，常用于运行工具和包内的命令行入口。</li></ul><p data-src-line="74" data-src-file="python/01-python-language/chapter-00-getting-started.md">跑通任意一种（比如 <code>python3 -c &quot;print(&#39;ok&#39;)&quot;</code> 输出 <code>ok</code>），就说明环境可用。</p><h2 id="_5-下一步" tabindex="-1" data-src-line="76" data-src-file="python/01-python-language/chapter-00-getting-started.md">5. 下一步 <a class="header-anchor" href="#_5-下一步" aria-label="Permalink to &quot;5. 下一步&quot;">​</a></h2><p data-src-line="78" data-src-file="python/01-python-language/chapter-00-getting-started.md">环境就绪后，进入<a href="./chapter-01-values-and-variables.html">值、变量与类型</a>，从值、对象与变量语义开始回顾语言核心机制。</p>`,29)])])}const y=a(p,[["render",o]]);export{g as __pageData,y as default};
